{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C52"],
      "claim": "GSK1322322, a piperazine-aniline pyrimidine oral drug, had absolute oral bioavailability of 77% in healthy volunteers in the fed state, supporting high F for the query's similar piperazine-aniline heteroaromatic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Brigatinib, which shares the piperazine-aniline and pyrimidine motif, had an estimated oral bioavailability of 46% in healthy volunteers, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Linezolid, a small oral antibiotic, showed 100% absolute oral bioavailability, demonstrating that small oral drugs with polar heteroaromatic/piperazine-like groups can achieve complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Encainide in healthy subjects had mean oral bioavailability of 30%, above the 20% threshold despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone extended-release had absolute oral bioavailability of 28% in healthy volunteers, a low-but-high value supporting F≥20% for moderately absorbed oral drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Rifapentine had 70% absolute oral bioavailability in healthy volunteers, supporting high F for a large lipophilic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Ketanserin had absolute oral bioavailability of 46.8% in healthy subjects, supporting moderate-to-high F for an oral small molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Tacrolimus oral bioavailability is approximately 20-25%, at the threshold but still supporting F≥20% for a poorly absorbed oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Venadaparib showed good oral bioavailability in patients, supporting high F for an oral kinase-inhibitor-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Praziquantel in patients with hepatic disease had oral bioavailability of 27.2%, above the 20% threshold despite disease-related impairment.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Apalutamide had approximately 100% absolute oral bioavailability in humans, supporting high F for an oral small-molecule drug.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high: multiple structurally related oral drugs with piperazine-aniline/heteroaromatic cores show absolute oral bioavailability values of 20-100%, all at or above the 20% threshold, with no affirmative evidence of F<20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself is included in the provided records; all evidence is from analogs.",
    "Some encainide records report low or variable bioavailability in individual patients, but mean values remain ≥20%.",
    "Tacrolimus F ~20-25% is near the threshold; however, the query is a smaller, more soluble molecule, so this is not a strong low-F signal.",
    "Transfer likelihood scores are uncalibrated and used only as relative structural relatedness signals."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

